	stroke(255);
	strokeWeight(2);
	background(0);
	for(let j = 0; j < height; j+= windowHeight ){
	beginShape();
	fill(0);
	for(let i = 0; i < width; i+= 200){

	curveVertex(i, j + (height)*noise(i + ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000) + t + j));

	}
  endShape();
	}
	t+= 0.002
}

